SINA_SMART["pharma-vigilance"] = {"lecture":"pharma-vigilance","title":"Pharmacovigilance","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"pharma-vigilance:e0","text":"PV: detection, assessment, understanding, prevention of adverse effects (WHO).","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"pharma-vigilance:e1","text":"About 1 in 3 US drugs has post-approval safety issues.","topic":"Why PV is needed","sec":1,"importance":"core","highYield":"untested"},{"id":"pharma-vigilance:e2","text":"Five 'too's: too few, too simple, too median-aged, too narrow, too brief.","topic":"Why PV is needed","sec":1,"importance":"core","highYield":"untested"},{"id":"pharma-vigilance:e3","text":"ADR: noxious effect at normal doses needing treatment, dose change or caution.","topic":"Why PV is needed","sec":1,"importance":"core","highYield":"untested"},{"id":"pharma-vigilance:e4","text":"Steps: collect, review, respond.","topic":"Steps and history","sec":2,"importance":"core","highYield":"untested"},{"id":"pharma-vigilance:e5","text":"1937 sulfanilamide-diethylene glycol: 107 deaths → 1938 FD&C Act.","topic":"Steps and history","sec":2,"importance":"core","highYield":"untested"},{"id":"pharma-vigilance:e6","text":"Serious unexpected ADR: report within 15 days.","topic":"Reporting timelines","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-vigilance:e7","text":"Fatal/life-threatening unexpected: 7 calendar days.","topic":"Reporting timelines","sec":3,"importance":"core","highYield":"untested"},{"id":"pharma-vigilance:e8","text":"Non-serious ADRs go in periodic safety reports.","topic":"Reporting timelines","sec":3,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1bkwib2":"a","gnaivi":"a","m580x3":"a","1tbjriy":"a","ptghp7":"a","jqojsa":"a","7frt42":"a","25ums4":"a","1w8g3fs":"a","1pw09w0":"a","2jf7dn":"a"},"mapCounts":{"verified":0,"auto":11,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"pharma-vigilance:e0":{"s":0,"u":["PV: detection, assessment, understanding, prevention of adverse effects (WHO).","WHO definition: pharmacovigilance (PV) is the science and activities relating to the detection, assessment, understanding and prevention of adverse drug effects or any other drug-related problem."],"dp":[{"h":"Why most drug risks appear after launch","t":"If an adverse effect occurs in 1 in 10,000 patients, a trial of a few thousand people will probably never see it. Once hundreds of thousands of people, including the old, the young and those on many other drugs, take the medicine for years, rare effects become visible. Pharmacovigilance is how those signals are caught and acted on. Source: the lecture's 'why we need PV' slides."}]},"pharma-vigilance:e1":{"s":1,"u":["About 1 in 3 US drugs has post-approval safety issues.","No drug is 100% safe; in the USA about 1 in 3 drugs has safety issues after approval."],"dp":[]},"pharma-vigilance:e2":{"s":1,"u":["Five 'too's: too few, too simple, too median-aged, too narrow, too brief.","The five 'too's of clinical trials: too few patients (rare AEs, about 0.1%, are missed), too simple (efficacy only, no co-medication), too median-aged (children and elderly excluded), too narrow (administration controlled by professionals), too brief (real use lasts years)."],"dp":[]},"pharma-vigilance:e3":{"s":1,"u":["ADR: noxious effect at normal doses needing treatment, dose change or caution.","An adverse drug reaction (ADR) is any noxious change suspected to be due to a drug at normal doses that needs treatment, dose reduction, or caution in future use."],"dp":[]},"pharma-vigilance:e4":{"s":2,"u":["Steps: collect, review, respond.","Steps : (1) collect side-effect reports (patient to doctor or directly to the company, then the regulator, e.g.","FDA); (2) review the data to find effects missed before; (3) respond (new label warnings, safety announcements), as with the lamotrigine cardiac warning, where experts cautioned against assuming it was unique among sodium-channel blockers."],"dp":[{"h":"Why reporting matters even for a single case","t":"Spontaneous reports are the raw material of pharmacovigilance: a regulator can only link a drug to a rare reaction if individual clinicians report what they see. A single well-documented report, added to others, can be the signal that leads to a warning or a withdrawal. Source: the lecture's steps in PV slide."}]},"pharma-vigilance:e5":{"s":2,"u":["1937 sulfanilamide-diethylene glycol: 107 deaths → 1938 FD&C Act.","History : in 1937 sulfanilamide was dissolved in diethylene glycol , tested only for flavour, look and smell, and shipped 633 times; 107 people died , leading to the 1938 Food, Drug and Cosmetic Act that strengthened the FDA."],"dp":[]},"pharma-vigilance:e6":{"s":3,"u":["Serious unexpected ADR: report within 15 days.","Serious ADR : death, life-threatening, hospitalisation, disability, congenital anomaly, or intervention needed to prevent permanent damage; expedited reporting: serious unexpected within 15 days , fatal or life-threatening unexpected within 7 calendar days .","Non-serious ADR (headache, insomnia): not expedited, included in periodic safety reports ."],"dp":[]},"pharma-vigilance:e7":{"s":3,"u":["Fatal/life-threatening unexpected: 7 calendar days.","Serious ADR : death, life-threatening, hospitalisation, disability, congenital anomaly, or intervention needed to prevent permanent damage; expedited reporting: serious unexpected within 15 days , fatal or life-threatening unexpected within 7 calendar days ."],"dp":[]},"pharma-vigilance:e8":{"s":3,"u":["Non-serious ADRs go in periodic safety reports.","Non-serious ADR (headache, insomnia): not expedited, included in periodic safety reports ."],"dp":[]}},"meta":{"1bkwib2":{"a":"recall","vg":"pharma-vigilance:e0/recall/1"},"gnaivi":{"a":"recall","vg":"pharma-vigilance:e1/recall/1"},"m580x3":{"a":"recall","vg":"pharma-vigilance:e2/recall/1"},"1tbjriy":{"a":"relationship","vg":"pharma-vigilance:e2/relationship/1"},"ptghp7":{"a":"recall","vg":"pharma-vigilance:e3/recall/1"},"jqojsa":{"a":"recall","vg":"pharma-vigilance:e6/recall/1"},"7frt42":{"a":"recall","vg":"pharma-vigilance:e7/recall/1"},"25ums4":{"a":"recall","vg":"pharma-vigilance:e8/recall/1"},"1w8g3fs":{"a":"relationship","vg":"pharma-vigilance:e5/relationship/1"},"1pw09w0":{"a":"recall","vg":"pharma-vigilance:e5/recall/1"},"2jf7dn":{"a":"recall","vg":"pharma-vigilance:e4/recall/1"}},"explRev":"a0e3ffe28108"};
